--Ejercicio 1SELECT yr, subject, winner  FROM nobel WHERE yr = 1950--Ejercicio 2SELECT winner  FROM nobel WHERE yr = 1962   AND subject = 'literature'--Ejercicio 3select yr, subjectfrom nobelwhere winner = 'Albert Einstein'--Ejercicio 4select winnerfrom nobelwhere yr >= 2000 and subject = 'Peace'--Ejercicio 5select * from nobel where yr between 1980 and 1989 and subject = 'literature'--Ejercicio 6SELECT * FROM nobel WHERE winner IN ('Theodore Roosevelt',                  'Thomas Woodrow Wilson',                  'Jimmy Carter',                  'Barack Obama')--Ejercicio 7select winner from nobel where winner like 'John%'--Ejercicio 8select * from nobel where (subject = 'physics' and yr = 1980) or (subject = 'chemistry' and yr = 1984)--Ejercicio 9select * from nobel where yr = '1980' and subject not in ('chemistry','medicine')--Ejercicio 10select * from nobelwhere (subject = 'Medicine' and yr < 1910) or (subject = 'Literature' and yr >= 2004)--Ejercicio 11select * from nobel where winner = 'PETER GRÜNBERG'--Ejercicio 12select * from nobel where winner = "EUGENE O'NEILL"--Ejercicio 13select winner, yr, subject from nobel where winner like 'Sir%'order by yr desc, winner asc --Ejercicio 14SELECT winner, subject  FROM nobel WHERE yr=1984 ORDER BY subject IN ('physics','chemistry'), subject, winner--Sin terminar, All vowels